const submissionsOfProgram = `-- name: SubmissionsOfProgram :many
SELECT s.id, s.user_id, s.project, s.from_day, s.to_day, s.program_app_id, s.status, s.error, s.token_hash, s.token_enc, s.trust_at_submission, s.packet, s.verified_minutes, s.mismatch_minutes, s.unbacked_minutes, s.counted_seconds, s.raw_seconds, s.parts_version, s.created_at, s.verified_at, s.decided_at, s.withdrawn_at FROM submissions s
LEFT JOIN LATERAL (
    SELECT d.value FROM submission_decisions d
    WHERE d.submission_id = s.id
    ORDER BY d.decided_at DESC, d.id DESC
    LIMIT 1
) latest ON true
WHERE s.program_app_id = $1
  AND ($2::text IS NULL OR s.status = $2::text)
  AND ($3::text IS NULL
       OR coalesce(latest.value, 'none') = $3::text)
ORDER BY s.created_at DESC, s.id
LIMIT $5 OFFSET $4
`

type SubmissionsOfProgramParams struct {
	AppID    pgtype.UUID
	Status   pgtype.Text
	Decision pgtype.Text
	SkipRows int32
	MaxRows  int32
}

// The submissions addressed to an app, newest first. A null status or
// decision is no filter; decision 'none' matches submissions without one.
func (q *Queries) SubmissionsOfProgram(ctx context.Context, arg SubmissionsOfProgramParams) ([]Submission, error) {
	rows, err := q.db.Query(ctx, submissionsOfProgram,
		arg.AppID,
		arg.Status,
		arg.Decision,
		arg.SkipRows,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Submission{}
	for rows.Next() {
		var i Submission
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Project,
			&i.FromDay,
			&i.ToDay,
			&i.ProgramAppID,
			&i.Status,
			&i.Error,
			&i.TokenHash,
			&i.TokenEnc,
			&i.TrustAtSubmission,
			&i.Packet,
			&i.VerifiedMinutes,
			&i.MismatchMinutes,
			&i.UnbackedMinutes,
			&i.CountedSeconds,
			&i.RawSeconds,
			&i.PartsVersion,
			&i.CreatedAt,
			&i.VerifiedAt,
			&i.DecidedAt,
			&i.WithdrawnAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

